/// <summary>
/// Base class for PricingAttribute table <c>METCustTable</c>
/// </summary>
public abstract class METGUPPricingAttributeMETCustTable extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
    protected METCustTable getTableRecord(Common _pricingObject)
    {
        METCustTable metCustTable;
        SalesTable  salesTable = _pricingObject as SalesTable;

        if (salesTable)
        {
            metCustTable = METCustTable::find(salesTable.CustAccount);
        }

        return metCustTable;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsRoot, qbdsMetCustTable;

        if (_qbdsMap && _qbdsMap.exists(tableStr(CustTable)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(CustTable));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(CustTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(CustTable), qbdsRoot);
            }
        }

        if (_qbdsMap && _qbdsMap.exists(tableStr(METCustTable)))
        {
            qbdsMetCustTable = _qbdsMap.lookup(tableStr(METCustTable));
        }
        else
        {
            qbdsMetCustTable = qbdsRoot.addDataSource(tableNum(METCustTable));
            qbdsMetCustTable.addLink(fieldNum(CustTable, AccountNum), fieldNum(METCustTable, AccountNum));
            qbdsMetCustTable.joinMode(JoinMode::ExistsJoin);

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(METCustTable), qbdsMetCustTable);
            }
        }

        return qbdsMetCustTable;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }
